def run(context):
    latest_equity_date = context['latest_equity_date']
    latest_snapshot_date = context['latest_snapshot_date']
    freshness_summary = {}
    recommendation = ""
    if latest_equity_date < latest_snapshot_date:
        freshness_summary = {'status': 'stale', 'message': 'Equity data lags behind snapshots'}
        recommendation = 'Update equity EOD data.'
    else:
        freshness_summary = {'status': 'current', 'message': 'Data is current for analysis'}
    return freshness_summary, recommendation

def run(context):
    # Analyzes the provided context of alerts, deals, and technical scores.
    analysis_summary = []
    for alert in context['alerts']:
        relevant_deals = [deal for deal in context['deals'] if deal['symbol'] == alert['symbol']]
        tech_status = next((score for score in context['technical_scores'] if score['symbol'] == alert['symbol']), None)
        if relevant_deals and tech_status:
            analysis_summary.append({
                'symbol': alert['symbol'],
                'insider_entity': alert['entity'],
                'deal_qty': sum([deal['qty'] for deal in relevant_deals]),
                'tech_signal': tech_status['trading_signal']
            })
    return {'analysis_summary': analysis_summary}
